}

#[derive(Debug, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct Clock {
    pub now: Time,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct QueueAttributes {
    attributes: AttributesView,
    counts: Counts,
}

